extra_css:
.kx-hero{text-align:center;padding:28px 0 8px}
.kx-eyebrow{color:var(--accent);font-size:13px;font-weight:700;letter-spacing:.08em;margin:0 0 10px}
.kx-h1{font-family:"Hiragino Mincho ProN","Yu Mincho","Noto Serif JP",serif;font-weight:600;font-size:clamp(30px,5.4vw,52px);line-height:1.3;margin:0 0 16px;letter-spacing:.02em}
.kx-h1 em{font-style:normal;color:var(--accent)}
.kx-lead{color:var(--muted);max-width:620px;margin:0 auto 22px;font-size:15px}
.kx-box{max-width:640px;margin:0 auto 14px;text-align:left;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:16px 18px 12px;box-shadow:0 8px 28px rgba(0,0,0,.06)}
.kx-type{min-height:84px;font-size:15px;line-height:1.8}
.kx-bar{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:12px;color:var(--muted)}
.kx-go{background:var(--fg);color:var(--bg);text-decoration:none;font-weight:700;font-size:13px;padding:7px 14px;border-radius:99px}
.kx-chips{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin:0 0 28px}
.kx-chips a{font-size:13px;color:var(--fg);text-decoration:none;border:1px solid var(--line);border-radius:99px;padding:5px 12px;background:var(--card)}
.kx-chips a:hover{border-color:var(--accent);color:var(--accent)}
.kx-vs{display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:center;background:var(--soft);border-radius:18px;padding:22px 16px;margin:0 0 22px}
.kx-side{padding:6px}.kx-k{font-size:12px;color:var(--muted)}.kx-v{font-size:clamp(20px,3.4vw,28px);font-weight:800;margin:4px 0}
.kx-side p{margin:0;font-size:13px;color:var(--muted)}.kx-side.on .kx-v{color:var(--accent)}
.kx-mid{font-family:serif;font-style:italic;color:var(--muted);font-size:18px}
@media (max-width:560px){.kx-vs{grid-template-columns:1fr}.kx-mid{margin:-4px 0}}
.kx-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0 0 22px}
.kx-stats div{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px 6px}
.kx-stats b{display:block;font-size:clamp(30px,5vw,42px);line-height:1.1;color:var(--accent2);font-variant-numeric:tabular-nums}
.kx-stats span{font-size:12px;color:var(--muted)}
.kx-steps{list-style:none;padding:0;margin:0 0 8px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px;text-align:left}
.kx-steps li{border-top:2px solid var(--accent);padding:10px 4px 0}.kx-steps b{color:var(--accent);font-size:12px;display:block}
.kx-steps strong{display:block;font-size:15px}.kx-steps span{font-size:12px;color:var(--muted)}
@media (max-width:560px){.kx-steps{grid-template-columns:1fr}}

/* theme: flat-shapes (2026-10-27) */
:root,:root:not(x){--bg:#1c1208;--fg:#fbf1e4;--muted:#cdb9a2;--line:#3e2c1b;--card:#271a0e;--soft:#332314;--accent:#ff8a3d;--accent2:#a678ff}
@media (prefers-color-scheme:dark){:root{--bg:#1c1208;--fg:#fbf1e4;--muted:#cdb9a2;--line:#3e2c1b;--card:#271a0e;--soft:#332314;--accent:#ff8a3d;--accent2:#a678ff}}
body{font-family:"Zen Maru Gothic","Hiragino Maru Gothic ProN",sans-serif;font-weight:500}
header{background:#1c1208;border-bottom:3px solid #ff8a3d}
.logo,.hero h1,article h1,.sec-h,article h2,.picks-h,.next-h,aside .box-h{font-weight:900}
.logo{color:#fbf1e4}.logo span{color:#ff8a3d}
.gnav a{background:#332314;color:#fbf1e4;border-radius:99px}
.gnav a:hover,.gnav a.on{background:#a678ff;color:#1c1208}
.kx-go{background:#ff8a3d;color:#1c1208}
.sec-h{border-bottom:0;padding-left:30px;position:relative}
.sec-h::before{content:"";position:absolute;left:0;top:50%;width:18px;height:18px;margin-top:-13px;border-radius:50%;background:#ff8a3d;box-shadow:8px 8px 0 -2px #a678ff}
.card{border:0;border-radius:18px;background:#271a0e;position:relative}
.thumb{border-radius:18px 18px 0 0}
.card::after{content:"";position:absolute;right:14px;bottom:14px;width:0;height:0;border-left:9px solid transparent;border-right:9px solid transparent;border-bottom:15px solid #a678ff;opacity:.8}
.card:hover{box-shadow:0 0 0 2px #ff8a3d}
.tag{background:#ff8a3d;color:#1c1208;font-weight:700}
article h2{background:#332314;border-left:0;border-radius:18px;padding:12px 16px 12px 46px;position:relative}
article h2::before{content:"";position:absolute;left:14px;top:50%;width:20px;height:20px;margin-top:-10px;border-radius:50%;background:#ff8a3d}
article h2::after{content:"";position:absolute;left:24px;top:50%;margin-top:-2px;border-left:7px solid transparent;border-right:7px solid transparent;border-bottom:12px solid #a678ff}
article h3{border-bottom:3px dotted #a678ff}
.eyecatch{border-radius:18px}
.lead,.toc,.shop,aside .box,.author{border:0;border-radius:18px;background:#271a0e}
.toc{box-shadow:inset 0 4px 0 #ff8a3d}
.note{border-left:6px solid #a678ff;border-radius:12px}
.picks{border:2px solid #ff8a3d;border-radius:18px}
.next{border:2px dashed #a678ff;border-radius:18px;background:#271a0e}
.avatar{background:#a678ff;color:#1c1208}
aside .box-h{border-bottom:3px solid #ff8a3d}
.mini img{border-radius:10px}.mini b{background:#a678ff;color:#1c1208}
th{background:#332314}
footer{background:#140c05;border-top:3px solid #a678ff}

/* article-base: 2026-10-27 記事ページの共通部分 */
.ax-time{display:inline-block;font-size:12px;margin-left:8px}
.ax-prog{position:fixed;left:0;right:0;top:0;height:4px;z-index:50;pointer-events:none}.ax-prog i{display:block;height:100%;width:0}
.toc li.now>a{font-weight:700}
.ax-tick{cursor:pointer}li.ax-tick{position:relative;padding-left:30px}ul>li.ax-tick{list-style:none}ul>li.ax-tick::marker{content:""!important}
li.ax-tick::before,tr.ax-tick td:first-child::before{content:"";position:absolute;left:4px;top:.45em;width:16px;height:16px;border:2px solid currentColor;border-radius:4px;opacity:.55}
.ax-tick.done{opacity:.55;text-decoration:line-through}li.ax-tick.done::after,tr.ax-tick.done td:first-child::after{content:"✓";position:absolute;left:7px;top:.05em;font-weight:800}
tr.ax-tick td:first-child{position:relative;padding-left:32px}tr.ax-tick td:first-child::before{left:8px;top:.6em}tr.ax-tick.done td:first-child::after{left:11px;top:.2em}
.ax-copy{display:block;margin:10px 0 0 auto;font:inherit;font-size:13px;font-weight:700;cursor:pointer}
@media print{.ax-prog,.ax-size,.ax-copy{display:none}}

/* article: shapes (2026-10-27) */
.ax-prog{height:6px;background:#271a0e}.ax-prog i{background:linear-gradient(90deg,#ff8a3d,#a678ff);border-radius:0 99px 99px 0}
.ax-time{background:#a678ff;color:#1c1208;border-radius:99px;padding:0 10px;font-weight:700}
.lead{border:2px solid #ff8a3d!important}.lead strong::before{content:"● ";color:#ff8a3d}
.toc{counter-reset:cz}.toc ol{list-style:none;padding-left:0}.toc li{counter-increment:cz;padding:3px 0}
.toc li::before{content:counter(cz);display:inline-block;width:22px;height:22px;line-height:22px;text-align:center;margin-right:8px;font-size:12px;font-weight:900;color:#1c1208;background:#ff8a3d;border-radius:50%}
.toc li:nth-child(3n+2)::before{background:#a678ff;border-radius:4px}.toc li:nth-child(3n)::before{background:#fbf1e4;clip-path:polygon(50% 0,100% 100%,0 100%);line-height:26px;font-size:10px}
.toc li.now a{color:#ff8a3d}
article ul li::marker{content:"▲ ";color:#a678ff;font-size:.8em}
